basicCode.vanilla:
import { createChatThread } from '@/components/ui/chat-thread';

const thread = createChatThread({ messages, labels });
document.querySelector('#app')?.append(thread);

extensibilityCode.vanilla:
// O trecho novo pousa no MESMO id; o fim desliga o streaming.
thread.append({ id: 'm-7', role: 'assistant', content: '', streaming: true });
for await (const parte of resposta) {
  acumulado += parte;
  thread.update('m-7', { content: acumulado });
}
thread.update('m-7', { streaming: false });   // aqui sai o anúncio único

extensibilityCode.react:
// A lista É a API: o id mantém a mensagem no lugar enquanto ela cresce.
const [messages, setMessages] = useState(inicial);

const patch = (id, campos) =>
  setMessages((atual) => atual.map((m) => (m.id === id ? { ...m, ...campos } : m)));

setMessages((atual) => [...atual, { id: 'm-7', role: 'assistant', content: '', streaming: true }]);
for await (const parte of resposta) patch('m-7', { content: (acumulado += parte) });
patch('m-7', { streaming: false });   // aqui sai o anúncio único

extensibilityCode.vue:
// A lista É a API: o id mantém a mensagem no lugar enquanto ela cresce.
const messages = ref(inicial);
const patch = (id, campos) => {
  const alvo = messages.value.find((m) => m.id === id);
  if (alvo) Object.assign(alvo, campos);
};

messages.value.push({ id: 'm-7', role: 'assistant', content: '', streaming: true });
for await (const parte of resposta) patch('m-7', { content: (acumulado += parte) });
patch('m-7', { streaming: false });   // aqui sai o anúncio único

