extensibilityCode.angular:
// A lista É a API: o id mantém a mensagem no lugar enquanto ela cresce.
readonly messages = signal<ChatMessage[]>(inicial);

private patch(id: string, campos: Partial<ChatMessage>) {
  this.messages.update((atual) =>
    atual.map((m) => (m.id === id ? { ...m, ...campos } : m)));
}

this.messages.update((atual) => [
  ...atual, { id: 'm-7', role: 'assistant', content: '', streaming: true },
]);
for await (const parte of resposta) this.patch('m-7', { content: (acumulado += parte) });
this.patch('m-7', { streaming: false });   // aqui sai o anúncio único

customizationCode.web:
/* A altura e a medida de leitura são da PÁGINA, não do componente. */
.conversa .nds-chat-thread {
  block-size: 32rem;
  --nds-chat-measure: 48rem;
}

